t.script:

// ===== ENHANCED SLIDESHOW WITH VIDEO + IMAGES =====

let currentSlideIndex = 0;
let autoSlideInterval;
let isAutoSlideActive = true;
let progressInterval;
let allSlides = [];
let totalSlides = 0;

// Initialize slideshow on page load
document.addEventListener('DOMContentLoaded', function() {
    // Get all slide items
    allSlides = document.querySelectorAll('.slide-item');
    totalSlides = allSlides.length;

    console.log('Total slides:', totalSlides);

    // Start auto-slide if multiple slides
    if (totalSlides > 1) {
        startAutoSlide();
    }

    // Setup video event listeners
    setupVideoListeners();
});

// Setup video-specific event listeners
function setupVideoListeners() {
    const video = document.getElementById('busVideo');
    if (video) {
        // Pause slideshow when video is playing
        video.addEventListener('play', function() {
            if (isAutoSlideActive) {
                stopAutoSlide();
            }
        });

        // Resume slideshow when video ends (optional)
        video.addEventListener('ended', function() {
            if (totalSlides > 1) {
                nextSlide();
                startAutoSlide();
            }
        });
    }
}

// Auto-slide functions
function startAutoSlide() {
    if (autoSlideInterval) clearInterval(autoSlideInterval);
    if (progressInterval) clearInterval(progressInterval);

    isAutoSlideActive = true;
    updatePlayPauseButton();

    autoSlideInterval = setInterval(() => {
        if (isAutoSlideActive) {
            nextSlide();
        }
    }, 5000); // 5 seconds interval

    updateProgressBar();
}

function stopAutoSlide() {
    if (autoSlideInterval) clearInterval(autoSlideInterval);
    if (progressInterval) clearInterval(progressInterval);
    isAutoSlideActive = false;
    updatePlayPauseButton();
}

function toggleAutoSlide() {
    if (isAutoSlideActive) {
        stopAutoSlide();
    } else {
        startAutoSlide();
    }
}

function updatePlayPauseButton() {
    const playPauseBtn = document.getElementById('playPauseBtn');
    if (playPauseBtn) {
        const icon = playPauseBtn.querySelector('i');
        if (isAutoSlideActive) {
            icon.className = 'fas fa-pause';
            playPauseBtn.title = 'Pause';
        } else {
            icon.className = 'fas fa-play';
            playPauseBtn.title = 'Play';
        }
    }
}

function updateProgressBar() {
    const progressBar = document.getElementById('progressBar');
    if (!progressBar || !isAutoSlideActive) return;

    if (progressInterval) clearInterval(progressInterval);

    let progress = 0;
    progressBar.style.width = '0%';

    progressInterval = setInterval(() => {
        progress += 2;
        progressBar.style.width = progress + '%';

        if (progress >= 100) {
            clearInterval(progressInterval);
        }
    }, 100); // Update every 100ms
}

// Navigation functions
function nextSlide() {
    if (totalSlides === 0) return;

    currentSlideIndex = (currentSlideIndex + 1) % totalSlides;
    updateSlide();
}

function previousSlide() {
    if (totalSlides === 0) return;

    currentSlideIndex = (currentSlideIndex - 1 + totalSlides) % totalSlides;
    updateSlide();
}

function goToSlide(index) {
    if (totalSlides === 0 || index < 0 || index >= totalSlides) return;

    currentSlideIndex = index;
    updateSlide();

    // Restart auto-slide
    if (isAutoSlideActive) {
        startAutoSlide();
    }
}

function updateSlide() {
    // Hide all slides
    allSlides.forEach(slide => {
        slide.classList.remove('active');
    });

    // Show current slide
    if (allSlides[currentSlideIndex]) {
        allSlides[currentSlideIndex].classList.add('active');
    }

    // Update thumbnails
    updateThumbnails();

    // Update indicators
    updateIndicators();

    // Handle video playback
    handleVideoPlayback();

    // Restart progress bar
    if (isAutoSlideActive) {
        updateProgressBar();
    }
}

function updateThumbnails() {
    const thumbnails = document.querySelectorAll('.thumbnail, .thumbnail.video-thumb');
    thumbnails.forEach((thumb, index) => {
        thumb.classList.toggle('active', index === currentSlideIndex);
    });
}

function updateIndicators() {
    const indicators = document.querySelectorAll('.slide-indicator');
    indicators.forEach((indicator, index) => {
        indicator.classList.toggle('active', index === currentSlideIndex);
    });
}

function handleVideoPlayback() {
    const video = document.getElementById('busVideo');

    // Pause all videos first
    document.querySelectorAll('video').forEach(v => {
        if (v !== video) v.pause();
    });

    const currentSlide = allSlides[currentSlideIndex];
    const slideType = currentSlide ? currentSlide.getAttribute('data-type') : null;

    if (slideType === 'video' && video) {
        // If we're on video slide, play it
        video.play().catch(err => {
            console.log('Video autoplay failed:', err);
        });
    } else if (video) {
        // If we're not on video slide, pause it
        video.pause();
        video.currentTime = 0;
    }
}

// Video control functions
function toggleVideoSound() {
    const video = document.getElementById('busVideo');
    const volumeIcon = document.getElementById('volumeIcon');

    if (video) {
        video.muted = !video.muted;
        if (volumeIcon) {
            volumeIcon.className = video.muted ? 'fas fa-volume-mute' : 'fas fa-volume-up';
        }
    }
}

function toggleFullscreen() {
    const video = document.getElementById('busVideo');

    if (video) {
        if (video.requestFullscreen) {
            video.requestFullscreen();
        } else if (video.webkitRequestFullscreen) {
            video.webkitRequestFullscreen();
        } else if (video.mozRequestFullScreen) {
            video.mozRequestFullScreen();
        } else if (video.msRequestFullscreen) {
            video.msRequestFullscreen();
        }
    }
}

// Pause slideshow on hover
document.addEventListener('DOMContentLoaded', function() {
    const imageGallery = document.querySelector('.image-gallery');

    if (imageGallery) {
        imageGallery.addEventListener('mouseenter', function() {
            if (isAutoSlideActive && totalSlides > 1) {
                stopAutoSlide();
            }
        });

        imageGallery.addEventListener('mouseleave', function() {
            if (totalSlides > 1) {
                startAutoSlide();
            }
        });
    }
});

// Keyboard navigation
document.addEventListener('keydown', function(e) {
    if (e.key === 'ArrowLeft') {
        previousSlide();
    } else if (e.key === 'ArrowRight') {
        nextSlide();
    } else if (e.key === ' ') {
        e.preventDefault();
        toggleAutoSlide();
    }
});

// Touch/swipe support for mobile
let touchStartX = 0;
let touchEndX = 0;

document.addEventListener('DOMContentLoaded', function() {
    const imageGallery = document.querySelector('.image-gallery');

    if (imageGallery) {
        imageGallery.addEventListener('touchstart', function(e) {
            touchStartX = e.changedTouches[0].screenX;
        });

        imageGallery.addEventListener('touchend', function(e) {
            touchEndX = e.changedTouches[0].screenX;
            handleSwipe();
        });
    }
});

function handleSwipe() {
    const swipeThreshold = 50;
    const diff = touchStartX - touchEndX;

    if (Math.abs(diff) > swipeThreshold) {
        if (diff > 0) {
            nextSlide();
        } else {
            previousSlide();
        }
    }
}

// ===== TAB NAVIGATION =====
function showTab(tabName) {
    const allContents = document.querySelectorAll('.tab-content');
    const allTabs = document.querySelectorAll('.tab');
    const targetContent = document.getElementById(tabName);
    const clickedTab = event.target;

    allContents.forEach(content => {
        if (content.classList.contains('active')) {
            content.style.opacity = '0';
            content.style.transform = 'translateY(10px)';
            setTimeout(() => {
                content.classList.remove('active');
            }, 200);
        }
    });

    allTabs.forEach(tab => {
        tab.classList.remove('active');
    });

    setTimeout(() => {
        targetContent.classList.add('active');
        targetContent.style.opacity = '0';
        targetContent.style.transform = 'translateY(10px)';
        targetContent.offsetHeight;
        targetContent.style.transition = 'all 0.4s cubic-bezier(0.4, 0, 0.2, 1)';
        targetContent.style.opacity = '1';
        targetContent.style.transform = 'translateY(0)';
        clickedTab.classList.add('active');
    }, 200);
}

// ===== IMAGE MODAL =====
function openImageModal(src, alt) {
    const modalImage = document.getElementById('modalImage');
    const modalTitle = document.getElementById('imageModalTitle');

    const img = new Image();
    img.onload = function() {
        modalImage.src = src;
        modalTitle.textContent = alt;
        const modal = new bootstrap.Modal(document.getElementById('imageModal'));
        modal.show();
    };
    img.src = src;
}

// ===== SHARE FUNCTION =====
function shareThisBus() {
    const busName = '';
    const currentUrl = window.location.href;
    const shareText = `Check out this amazing ${busName} - Premium Bus with Luxury Features!`;

    if (navigator.share) {
        navigator.share({
            title: busName + ' - Annapurna Travels',
            text: shareText,
            url: currentUrl
        }).catch(err => console.log('Error sharing:', err));
    } else {
        showShareModal(busName, shareText, currentUrl);
    }
}

function showShareModal(busName, shareText, url) {
    const shareModal = document.createElement('div');
    shareModal.className = 'modal fade';
    shareModal.id = 'shareModal';
    shareModal.innerHTML = `
        <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">
                        <i class="fas fa-share-alt text-primary me-2"></i>
                        Share ${busName}
                    </h5>
                    <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
                </div>
                <div class="modal-body">
                    <div class="mb-3">
                        <label class="form-label fw-bold">Share Link:</label>
                        <div class="input-group">
                            <input type="text" class="form-control" id="shareUrl" value="${url}" readonly>
                            <button class="btn btn-outline-primary" onclick="copyToClipboard('shareUrl')">
                                <i class="fas fa-copy"></i> Copy
                            </button>
                        </div>
                    </div>
                    <div class="mb-3">
                        <label class="form-label fw-bold">Share on Social Media:</label>
                        <div class="d-flex gap-2 flex-wrap">
                            <a href="https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(url)}"
                               target="_blank" class="btn btn-primary btn-sm">
                                <i class="fab fa-facebook-f me-1"></i> Facebook
                            </a>
                            <a href="https://twitter.com/intent/tweet?text=${encodeURIComponent(shareText)}&url=${encodeURIComponent(url)}"
                               target="_blank" class="btn btn-info btn-sm text-white">
                                <i class="fab fa-twitter me-1"></i> Twitter
                            </a>
                            <a href="https://wa.me/?text=${encodeURIComponent(shareText + ' ' + url)}"
                               target="_blank" class="btn btn-success btn-sm">
                                <i class="fab fa-whatsapp me-1"></i> WhatsApp
                            </a>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    `;

    document.body.appendChild(shareModal);
    const modal = new bootstrap.Modal(shareModal);
    modal.show();

    shareModal.addEventListener('hidden.bs.modal', function() {
        document.body.removeChild(shareModal);
    });
}

function copyToClipboard(elementId) {
    const element = document.getElementById(elementId);
    element.select();
    element.setSelectionRange(0, 99999);

    try {
        document.execCommand('copy');
        showToast('Link copied to clipboard!', 'success');
    } catch (err) {
        console.error('Could not copy text: ', err);
        showToast('Failed to copy link', 'error');
    }
}

function showToast(message, type = 'info') {
    const toast = document.createElement('div');
    toast.className = `alert alert-${type === 'success' ? 'success' : 'danger'} position-fixed`;
    toast.style.cssText = `
        top: 20px;
        right: 20px;
        z-index: 9999;
        min-width: 250px;
        animation: slideIn 0.3s ease-out;
    `;
    toast.innerHTML = `
        <i class="fas fa-${type === 'success' ? 'check-circle' : 'exclamation-circle'} me-2"></i>
        ${message}
    `;

    document.body.appendChild(toast);

    setTimeout(() => {
        toast.style.animation = 'slideOut 0.3s ease-in';
        setTimeout(() => {
            if (document.body.contains(toast)) {
                document.body.removeChild(toast);
            }
        }, 300);
    }, 3000);
}

// Enhanced scroll animations
document.addEventListener('DOMContentLoaded', function() {
    const observerOptions = {
        root: null,
        rootMargin: '0px 0px -100px 0px',
        threshold: 0.1
    };

    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.style.animationPlayState = 'running';
            }
        });
    }, observerOptions);

    document.querySelectorAll('.feature-card, .bus-title, .bus-subtitle, .key-features, .cta-buttons').forEach(el => {
        observer.observe(el);
    });
});
